const icons = {
  ok: <Check />,
  error: <Cross />,
  warn: <Alert />,
};

function Badge({ type }) {
  return icons[type] ?? null;
}

const Row = memo(function Row({ item, onPick }) {
  return <li onClick={() => onPick(item)}>{item.name}</li>;
});

function List({ items }) {
  const onPick = useCallback((i) => select(i), []);
  return items.map((i) => (
    <Row key={i.id} item={i} onPick={onPick} />
  ));
}

