const views = {
  home: Home,
  about: About,
  contact: Contact,
};

function Page({ name }) {
  const View = views[name] ?? NotFound;
  return <View />;
}

function Handle() {
  function down(e) {
    e.currentTarget.setPointerCapture(e.pointerId);
    console.log(e.pointerType);
  }
  return <div onPointerDown={down} />;
}

function Card() {
  return (
    <div
      data-testid='card'
      custom-attr='valor'
      isActive={true}
    />
  );
}

function Names({ users }) {
  return (
    <ul>
      {users
        .filter((u) => u.active)
        .map((u) => <li key={u.id}>{u.name}</li>)}
    </ul>
  );
}

function Link({ href, kind }) {
  return (
    <a
      href={href}
      className={`btn btn-${kind}`}
    >
      Abrir
    </a>
  );
}

import PropTypes from 'prop-types';

Users.propTypes = {
  users: PropTypes.arrayOf(
    PropTypes.shape({
      id: PropTypes.number.isRequired,
      name: PropTypes.string,
    })
  ).isRequired,
};

